def finish_bag(self, user_id: str, bag_id: str, on: date) -> bool:
    """Finish: the stored bag again with finished_on set, as a new record (never a delete), like a retraction.
    Finishing a finished bag writes nothing and keeps its date, so a resend from the outbox is harmless."""
    prev = self._owned(self.bags, bag_id, user_id)
    if prev is None or prev.deleted:
        raise NotFound(bag_id)
    if prev.item.finished_on:
        return False
    if on > datetime.now(UTC).date() + timedelta(days=1):  # the same day's grace as a roast date
        raise Invalid("That date is in the future.")
    self._commit(self.bags, bag_id, prev.item.model_copy(update={"finished_on": on}), "bags")
    return True

