new='''const KIND = { shot: "A shot", retract: "Undoing a shot", restore: "Bringing a shot back", bag: "A bag", finish: "Finishing a bag",'''
assert s.count(old)==1; s=s.replace(old,new)
old='''// Theme and hand live in cookies so the server renders them; no flash of the other layout.'''
new='''// A bag's Finish: a second tap, then a record with finished_on (never a delete), queued like any write. It's
// taken back on Edit bag ("Still using it"). The day is the phone's, so one finished offline keeps its day.
function finishBag(b) {
  const id = b.dataset.finish;
  const box = b.closest("[data-finish-box]");
  const label = b.textContent;
  b.addEventListener("blur", () => { b.textContent = label; });
  b.addEventListener("click", async () => {
    if (b.textContent === label) {
      b.textContent = "Tap again to finish it";
      tick();
      return;
    }
    b.disabled = true;
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
    try {
      await send(`finish:${id}`, `/api/bags/${id}/finish`, { finished_on: today });
      await clearBagPages().catch(() => {});
      tick(8);
      go(location.pathname, `Bag finished: ${b.dataset.name}`);
    } catch (err) {
      if (err instanceof Rejected) {
        hint(box, err.message);
        b.disabled = false;
        b.textContent = label;
        return;
      }
      // No connection: the record waits in the outbox and goes through later.
      b.hidden = true;
      hint(box, "Finished on this phone. It syncs when you’re back online.");
    }
  });
}

// Theme and hand live in cookies so the server renders them; no flash of the other layout.'''
assert s.count(old)==1; s=s.replace(old,new)
old='''  for (const b of document.querySelectorAll("[data-retract]")) retractShot(b);'''
new=old+'''\n  for (const b of document.querySelectorAll("[data-finish]")) finishBag(b);'''
assert s.count(old)==1; s=s.replace(old,new)
open(p,'w').write(s)
EOF
node --check app/static/app.js && echo ok

